26	export function ProjectInvoices({ projectId }: { projectId: number }) {
27	  const [invoices, setInvoices] = useState<Invoice[]>([]);
28	  const [amount, setAmount] = useState('');
29	  const [error, setError] = useState('');
30	  const [sort, setSort] = useState<'id' | 'due'>('id');
31	  const [openInvoiceId, setOpenInvoiceId] = useState<number | null>(null);
32	  const [openStatus, setOpenStatus] = useState('');
33	
34	  async function load(order: 'id' | 'due' = sort) {
35	    const res = await fetch(`/api/projects/${projectId}/invoices?sort=${order}`);
36	    setInvoices(await res.json());
37	  }
38	
39	  // The opened invoice's status is derived from its payments, so re-read it on open and whenever a
40	  // payment is recorded against it.
41	  async function loadInvoice(invoiceId: number) {
42	    const res = await fetch(`/api/invoices/${invoiceId}`);
43	    if (!res.ok) {
44	      return;
45	    }
46	    const inv: Invoice = await res.json();
47	    setOpenStatus(inv.status);
48	  }
49	
50	  useEffect(() => {
51	    void load();
52	  }, [projectId]);
53	
54	  useEffect(() => {
55	    if (openInvoiceId !== null) {
56	      void loadInvoice(openInvoiceId);
57	    }
58	  }, [openInvoiceId]);
