60	  async function sortByDue() {
61	    setSort('due');
62	    await load('due');
63	  }
64	
65	  async function onSubmit(e: React.FormEvent) {
66	    e.preventDefault();
67	    const value = Number(amount);
68	    if (!(value > 0)) {
69	      setError('Amount must be greater than zero');
70	      return;
71	    }
72	    setError('');
73	    const res = await fetch(`/api/projects/${projectId}/invoices`, {
74	      method: 'POST',
75	      headers: { 'Content-Type': 'application/json' },
76	      body: JSON.stringify({ amount: Number(amount) }),
77	    });
78	    if (!res.ok) {
79	      return;
80	    }
81	    setAmount('');
82	    await load();
83	  }
84	
85	  async function send(invoiceId: number) {
86	    const res = await fetch(`/api/invoices/${invoiceId}/send`, { method: 'POST' });
87	    if (!res.ok) {
88	      return;
89	    }
90	    await load();
91	  }
92	
93	  const total = invoices.reduce((sum, inv) => sum + Number(inv.amount), 0);
94	
95	  if (openInvoiceId !== null) {
