101	        </p>
102	        <InvoiceLineItems
103	          invoiceId={openInvoiceId}
104	          onClose={() => {
105	            setOpenInvoiceId(null);
106	            void load();
107	          }}
108	        />
109	        <InvoicePayments
110	          invoiceId={openInvoiceId}
111	          onRecorded={() => void loadInvoice(openInvoiceId)}
112	        />
113	      </section>
114	    );
115	  }
116	
117	  return (
118	    <section data-testid="project-invoices">
119	      <h2>Invoices</h2>
120	
121	      <form data-testid="invoice-form" onSubmit={onSubmit}>
122	        <input
123	          data-testid="invoice-form-amount"
124	          placeholder="Amount"
125	          value={amount}
126	          onChange={(e) => setAmount(e.target.value)}
127	        />
128	        <button type="submit" data-testid="invoice-form-submit">
129	          Add invoice
